 import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture as sampleTexture, uv as uvNode, color as colorNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry, BoxGeometry, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors || config.colors || {};
  const paper = colors.paper || '#e8ecf2';
  const ink = colors.ink || '#16161d';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const width = 1.28;
  const height = 0.8;
  const depth = 0.06;

  const root = new Group();

  const backdropGeo = new PlaneGeometry(width + 0.12, height + 0.12);
  const backdropMat = new MeshBasicNodeMaterial({ color: surface, side: DoubleSide });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.06;
  root.add(backdrop);

  const cardGeo = new PlaneGeometry(width, height);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });
  cardMat.colorNode = colorNode(paper);
  cardMat.needsUpdate = true;

  const card = new Mesh(cardGeo, cardMat);
  card.renderOrder = 1;
  root.add(card);

  const frameGroup = new Group();
  const frameMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    side: DoubleSide,
    depthWrite: false,
  });
  frameGroup.visible = false;
  root.add(frameGroup);

  const borderZ = 0.02;
  const thick = 0.018;
  const pad = 0.03;

  const topGeo = new BoxGeometry(width + pad * 2 + thick * 2, thick, depth);
  const bottomGeo = new BoxGeometry(width + pad * 2 + thick * 2, thick, depth);
  const leftGeo = new BoxGeometry(thick, height + pad * 2, depth);
  const rightGeo = new BoxGeometry(thick, height + pad * 2, depth);

  const topFrame = new Mesh(topGeo, frameMat);
  topFrame.position.set(0, height / 2 + pad + thick / 2, borderZ);
  const bottomFrame = new Mesh(bottomGeo, frameMat);
  bottomFrame.position.set(0, -(height / 2 + pad + thick / 2), borderZ);
  const leftFrame = new Mesh(leftGeo, frameMat);
  leftFrame.position.set(-(width / 2 + pad + thick / 2), 0, borderZ);
  const rightFrame = new Mesh(rightGeo, frameMat);
  rightFrame.position.set(width / 2 + pad + thick / 2, 0, borderZ);

  frameGroup.add(topFrame, bottomFrame, leftFrame, rightFrame);

  const badgeGroup = new Group();
  badgeGroup.position.set(width / 2 - 0.18, height / 2 - 0.18, 0.04);
  const badgeGeo = new CircleGeometry(0.07, 24);
  const badgeMat = new MeshBasicNodeMaterial({ color: accent, side: DoubleSide, transparent: true });
  const badge = new Mesh(badgeGeo, badgeMat);
  badgeGroup.add(badge);
  root.add(badgeGroup);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        tex.colorSpace = ctx.THREE.SRGBColorSpace;

        const imgW = tex.image?.width || 512;
        const imgH = tex.image?.height || 320;
        const repeatX = 512 / imgW;
        const repeatY = 320 / imgH;

        tex.repeat.set(repeatX, repeatY);
        tex.offset.set(0, 1 - repeatY);
        tex.updateMatrix();
        tex.needsUpdate = true;

        const texNode = sampleTexture(tex, uvNode());
        cardMat.colorNode = texNode;
        cardMat.opacityNode = texNode.a;
        cardMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  const cinematic = config.cinematicPrimitives || config.intent?.visualSpec?.cinematicPrimitives || [];
  const primitiveRefs = [];
  for (const p of cinematic) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const ref = ctx.primitives[p.name](root, p.params || {});
      if (ref) primitiveRefs.push(ref);
    }
  }

  let hoverTween = null;
  let pressTween = null;
  let focusTween = null;
  let baseY = root.position.y;

  function setStock(inStock) {
    badgeMat.color.set(inStock ? accent : surface);
    badgeMat.opacity = inStock ? 0.95 : 0.35;
  }

  setStock(true);

  root.userData.handlers = {
    onPointerOver: () => {
      if (hoverTween) hoverTween.kill();
      if (pressTween) pressTween.kill();
      baseY = root.position.y;
      hoverTween = gsap.to(root.position, {
        y: baseY + 0.15,
        duration: 0.35,
        ease: 'power2.out',
      });
    },
    onPointerOut: () => {
      if (hoverTween) hoverTween.kill();
      if (pressTween) pressTween.kill();
      hoverTween = gsap.to(root.position, {
        y: baseY,
        duration: 0.35,
        ease: 'power2.out',
      });
    },
    onPointerDown: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        onComplete: () => {
          ctx.emit('hub-journal.select', { id: config.id || 'journal-card-3' });
        },
      });
    },
    onPointerUp: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'power2.out',
      });
    },
    onFocus: () => {
      frameGroup.visible = true;
      if (focusTween) focusTween.kill();
      focusTween = gsap.to(frameMat, {
        opacity: 0.9,
        duration: 0.25,
        ease: 'power2.out',
      });
    },
    onBlur: () => {
      if (focusTween) focusTween.kill();
      focusTween = gsap.to(frameMat, {
        opacity: 0,
        duration: 0.2,
        ease: 'power2.out',
        onComplete: () => {
          frameGroup.visible = false;
        },
      });
    },
  };

  root.userData.setStock = setStock;
  root.userData.updateStock = setStock;

  root.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    if (focusTween) focusTween.kill();

    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(frameMat);

    cardGeo.dispose();
    backdropGeo.dispose();
    badgeGeo.dispose();
    topGeo.dispose();
    bottomGeo.dispose();
    leftGeo.dispose();
    rightGeo.dispose();

    cardMat.dispose();
    backdropMat.dispose();
    frameMat.dispose();
    badgeMat.dispose();

    if (loadedTexture) loadedTexture.dispose();

    for (const ref of primitiveRefs) {
      if (ref.cleanup) ref.cleanup();
      if (ref.timeline) ref.timeline.kill();
    }
  };

  return root;
}
